"""Agent eval harness: run each task, grade the outcome, report a pass rate."""
import json

def load_tasks(path):
    return [json.loads(l) for l in open(path)]

def grade(task, response):
    # outcome-based reward: did the response contain the expected marker?
    return 1.0 if task["expected"] in response else 0.0

def evaluate(agent, tasks):
    scores = [grade(t, agent(t)) for t in tasks]
    return {"pass_rate": sum(scores) / len(scores)}

if __name__ == "__main__":
    from my_agent import agent
    print(evaluate(agent, load_tasks("tasks.jsonl")))

